# -*- coding: utf-8 -*-
"""矛盾驱动补盲 · 批次C12（v10 新域 8 簇+直答：彩礼/丧偶式育儿/房价/医疗费用/教育分流/短视频/农村空心化/旅游宰客）
同时移除 v9 老字号非遗簇的泛词「越来越少」（避免抢答 v10 农村题）。
"""
def patch(path):
    src = open(path, encoding="utf-8").read()

    # 1) 移除老字号非遗簇泛词「越来越少」（「为什么农村年轻人越来越少」会被抢答）
    old_anchor_c = '    "老字号非遗": ["老字号", "越来越少", "非遗手艺", "没人学",'
    new_anchor_c = '    "老字号非遗": ["老字号", "非遗手艺", "没人学",'
    assert old_anchor_c in src, "laozihao anchor missing"
    src = src.replace(old_anchor_c, new_anchor_c, 1)

    # 2) 插入 8 新簇（anchor 用「注意机制」簇行，缩进干净）
    anchor_c = '    "注意机制": ["注意机制", "选择性注意", "分散注意", "什么是注意机制"],'
    new_c = '''    "彩礼": ["彩礼越来越高", "彩礼", "不给彩礼", "女方家同意",
             "用钱证明", "彩礼多少", "彩礼合理", "嫁妆", "彩礼和嫁妆"],
    "丧偶式育儿": ["育儿都是妈妈", "爸爸去哪儿", "赚钱养家", "爸爸负责赚钱养家",
             "育儿分工", "育儿怎么分工", "爸爸参与育儿", "怎么让爸爸",
             "育儿"],
    "房价": ["房价这么高", "房价", "买不起房", "买房", "房价跌了",
            "不买房", "租房过一辈子", "住得起", "必需品还是投资品",
            "房贷", "租房"],
    "医疗费用": ["一场大病", "大病拖垮", "拖垮一个家", "医生工资",
            "工资高一点", "看得起病", "浪费医疗", "医保", "医疗费用"],
    "教育分流": ["中考分流", "中考就要分流", "职高生", "职高", "被看不起",
            "技术工人", "分流早一点", "学技术", "普高", "职业教育",
            "教育分流"],
    "短视频": ["刷短视频", "短视频", "停不下来", "比书好看", "不看短视频",
            "落伍", "刷而不沉迷", "怎么利用", "被利用", "刷视频"],
    "农村空心化": ["农村年轻人", "农村越来越空", "谁种地", "进城打工",
            "打工赚钱", "留在农村", "年轻人留在", "农村怎么留住人",
            "乡村振兴", "农村"],
    "旅游宰客": ["景区总宰客", "宰客", "旅游越来越贵", "景区不赚钱",
            "怎么维护", "定价高一点", "商家定价", "旅游体验", "景区赚钱",
            "玩得开心", "不被坑", "旅游"],'''
    assert anchor_c in src, "cluster anchor missing"
    src = src.replace(anchor_c, new_c + "\n    " + anchor_c, 1)

    # 3) 插入 8 直答（anchor 用「注意机制」直答行）
    anchor_d = '    "注意机制": "注意机制是认知资源的选择性分配——选择性注意（聚焦）/分散注意（多任务）/持续注意；对应CSPMN只匹配激活条件空间",'
    new_d = '''    "彩礼": "彩礼越来越高、不给彩礼女方不同意，是『习俗人情』vs『小家庭负担』的矛盾——彩礼本是两家结亲的诚意（旧社会女方嫁女少个劳力，彩礼是补偿），但演变成『行情攀比』（看别人多少我也要多少/卖女儿心态）后，成了压垮年轻人婚姻的第一道坎。真相：①彩礼为什么越来越高——三因素：攀比（村里看齐/越涨越高）、面子（彩礼=女儿身价）、性别比失衡（男多女少，男方竞争抬价）——不是『女方贪心』单方面，是结构性抬价；②彩礼是卖女儿还是诚意——看用途：彩礼带回小家庭（陪嫁返还）=两个家庭帮一个新家（合理），彩礼留给娘家/父母（不返还）=把女儿当商品（卖女儿）；③不给彩礼女方家同意吗——看两家人怎么谈：硬不给（无视习俗）伤感情，全给（掏空家底/借债）伤小家庭，正解是『量力而行+用途透明』；④爱情为什么要用钱证明——爱情确实不用钱证明，但婚姻要（柴米油盐/房子/养娃），彩礼谈的不是爱是『两家的诚意和底线』——不谈钱伤感情，只谈钱伤爱情。合理的方式：①量力而行——彩礼不超过男方家庭年收入的合理比例（别借债结婚，债是婚后第一个矛盾）；②用途透明——两家说清楚：彩礼+嫁妆都用于小家庭（买房/装修/储蓄），不是给某一家；③尊重差异——女方坚持高彩礼有她的理由（安全感/传统），男方嫌高有他的难处（家底），谈不拢的核心是『信任』不是『数字』；④法律底线——借婚姻索取财物违法（法律不支持卖女儿式彩礼），感情破裂可以协商返还。核心：彩礼是习俗不是买卖——给得起的是诚意，给不起的是负担，谈得拢的是两家，谈不拢的是生意",
    "丧偶式育儿": "育儿都是妈妈的事、爸爸只负责赚钱，是『传统分工惯性』vs『现代育儿需要』的矛盾——旧分工（男主外女主内）在以前行得通（妈妈全职带娃），现在双职工家庭妈妈也要上班，育儿却还是默认妈妈包办，爸爸『赚钱养家就够了』成了缺席的借口。真相：①为什么育儿都是妈妈——三重惯性：社会默认（妈妈天生会带娃/爸爸是帮手）、职场结构（产假只有妈妈/爸爸不休陪产假）、逃避心理（带娃累，爸爸乐得被说『不会带』就不用带）——不是妈妈更会带，是妈妈被默认承担；②爸爸赚钱养家还不够吗——不够：赚钱是家庭责任之一，不是全部，孩子的成长需要陪伴（爸爸的陪伴有独特价值：游戏方式/冒险精神/规则感），『我赚钱你带娃』是分工不是甩锅，前提是妈妈也上班（双职工还单方带娃=妈妈打两份工）；③男人天生不会带孩子吗——不是天生不会，是没练过：喂奶换尿布陪玩都是技能，妈妈也不是天生会（第一次都手忙脚乱），爸爸『不会』是练习缺失不是能力缺失，越不做越不会（恶性循环）；④育儿分工不公平的代价——妈妈累垮（身心俱疲/怨气）/孩子缺爸爸的陪伴/夫妻感情磨损（『丧偶式育儿』是离婚率上升的原因之一）。怎么分工：①责任清单化——把育儿拆成具体事项（喂/哄/陪玩/接送/家长会/生病护理），按时间分配（一人一晚/周末轮换），看得见的公平才公平；②从『帮忙』到『负责』——爸爸不是帮妈妈带孩子，是带自己的孩子（妈妈不在也能独立带一天）；③互相体谅——妈妈别嫌爸爸做得不完美（做了就鼓励，标准别太高），爸爸别用『我不会』逃避（不会就学，陪产假/育儿假用起来）；④制度支持——产假/陪产假平等化（爸爸休陪产假=从第一天就参与），社会观念（『奶爸』是加分不是丢人）。核心：育儿是两个人的工程——妈妈不是默认承包人，爸爸不是旁观者，孩子的童年只有一次，缺席补不回来",
    "房价": "房价高、年轻人买不起房，是『居住需求』vs『市场定价』的矛盾——房子本质是住的（居住权），但在市场里它同时是资产（保值增值/学区/户口绑定），当房子被当成投资品炒，价格就脱离了居住价值，年轻人买不起。真相：①为什么房价这么高——三重叠加：土地财政（地方政府卖地收入支撑基建，地价推高房价）、城市化（人口涌入城市，需求集中）、金融属性（房子被当投资品，有钱人囤/贷款炒，价格被资金推高）——高房价是『土地+人口+金融』共同抬起来的，不是开发商单方面黑心；②年轻人买不起房怎么办——现实分层：一线城市核心区（普通人很难买，接受现实/租房/置换）、二三线/郊区（努力够得着）、保障房/共有产权（政策在补位）——『买不起核心区』不等于『无处安身』；③房价跌了买房的人亏了怎么办——这就是『房子是资产』的另一面：涨的时候享受增值，跌的时候承担贬值，资产有涨跌是常态，『房价只涨不跌』才是幻觉，炒房者要为自己的投资决策负责（政策也在挤泡沫）；④不买房租房过一辈子行吗——行且越来越多：租售同权在推进（子女入学/公积金租房），租金的现金流压力远小于房贷，『租房没面子』是社会观念不是生活必需——关键不是『有没有房本』是『住得稳不稳』。怎么住得起：①先租后买/先小后大——不一步到位，先上车（小户型/远一点）再置换；②利用政策——公积金/首套房优惠/共有产权/保障性租赁住房，该申请就申请；③量力而行——月供不超过收入30-40%，『六个钱包+三十年房贷』透支的是整个家庭的抗风险能力；④观念松动——幸福不绑定房产证，租得安稳+过得充实，比背债住大房子更健康。核心：房子是用来住的不是用来炒的——个人策略是在这个前提下，先解决『住』再考虑『产』",
    "医疗费用": "一场大病能拖垮一个家、看病贵，是『健康权』vs『医疗成本』的矛盾——医疗真的很贵（设备/药品/人才/研发都要钱），但个人扛不起这个贵（一场大病几十万），矛盾在『贵』由谁承担：全自费（个人扛）vs 医保/保险/国家（社会分担）。真相：①为什么看病这么贵——成本结构：检查设备（CT/MRI一台几百万，检查费要摊回）、药品研发（新药研发十几亿，药价要收回）、人才（医生培养十几年，服务费要合理）、医院运营（水电人工）——医疗是重资产行业，『贵』有客观成本，不是医院单方面黑心；②一场大病为什么拖垮一个家——大病账单（几十万~上百万）远超普通家庭储蓄（中国家庭平均存款约20万），医保有封顶线/目录限制（进口药/特效药自费），『因病返贫』是真实存在——不是家庭不努力，是风险太大个人扛不动；③医生工资高一点有错吗——没错：医生是高强度高风险高投入职业（培养周期长/值夜班/医闹风险），合理的医生收入是医疗质量的保障，『医生工资高』和『看病贵』不是一回事——贵在检查和药，不该省在医生服务上；④医院黑心还是本来就这么贵——部分是（过度检查/开贵药/回扣），部分是结构（成本+医保控费矛盾），要打击的是『过度医疗』（为提成多检查多开药），不该否定合理的医疗成本。怎么看得起病：①医保基础——职工/居民医保一定交（这是国家给的基础保障，个人+单位+财政三方出钱）；②商业保险补充——重疾险/百万医疗险（每年几百~几千，保额几十万起），医保+商保才是完整防护网（尤其家里有老人的）；③日常预防——体检/生活习惯（预防比治疗便宜得多，大部分大病早期可干预）；④看病策略——小病社区医院（便宜快）、大病专科医院（对症）、不迷信偏方（耽误病情更贵）；⑤制度——医保谈判（药品降价进医保）、分级诊疗、大病救助（民政兜底）。核心：大病风险不能靠个人硬扛——医保打底、商保补充、预防在前，把『一场病拖垮一个家』的概率降到最低",
    "教育分流": "中考分流、职高被看不起，是『人人有出路』vs『教育分层』的矛盾——社会需要两种人（研究型的/技术型的），中考把 15 岁的孩子分成『考得上普高』和『去职高』，本意是因材施教（不适合学术的早点学技能），但现实中职高=差生收容所（管理松/出路窄/被歧视），分流成了『淘汰』。真相：①为什么中考就分流——教育资源的现实：高中名额有限（普高录取率约50-60%），大学需要学术基础，强行让所有人上普高→大学→所有人都学不进去/毕业即失业，分流是『让不适合学术的人早走技能路』——逻辑没错，错在执行；②职高生为什么被看不起——三重歧视：社会观念（万般皆下品，唯有读书高）、职高现状（管理差/生源差/学不到真技术，恶性循环）、就业回报（职高毕业进工厂，收入低地位低）——被看不起的不是职高本身，是『职高=没出息』的标签；③都去上大学谁做技术工人——这就是分流的合理性：社会需要工程师也需要技师（德国制造业强，靠的就是双元制职业教育，技工收入体面受尊重），『都上大学』会造成结构性失业（大学生过剩+技工荒）；④分流早一点不好吗——理论好（早学技术早成才），现实残酷：15岁心智未成熟就被贴标签，『早分流』在保障不足时=早淘汰，德国的早分流有完善职教体系兜底，我们的职教还在补课。怎么选/怎么改：①个人选择——普高：走学术路线（适合坐得住/成绩中上）；职高：走技能路线（适合动手强/对学术没兴趣），选择标准不是『面子』是『哪条路能走下去』——职高选专业看就业（数控/护理/汽修等缺口大）；②职教改革——升学通道（职教高考/专升本，职高生也能考大学）、产教融合（校企合作，毕业即就业）、师资设备投入；③观念转变——德国技工收入不低于白领，『技术工人』是职业不是屈就，社会越尊重技能，分流越不伤人；④政策——普职比要弹性（别一刀切50%），职高要办出质量（让家长放心把孩子送去）。核心：分流不是淘汰是分路——关键是每条路都有出路，孩子的价值不该由『考没考上普高』定义",
    "短视频": "刷短视频停不下来、比书好看，是『即时快乐』vs『长期价值』的矛盾——短视频是精心设计的『快乐机器』（15秒一个刺激/算法精准喂你爱看的），书是慢回报（要读进去才爽），大脑天然选快的，不是你没意志力，是设计者比你更懂多巴胺。真相：①为什么刷短视频停不下来——三设计：无限下滑（没有『看完』的终点，永远有下一个）、即时奖励（15秒一个笑点/爽点，比游戏还短频快）、算法投喂（AI知道你爱看什么，越刷越精准，越精准越上瘾）——这是产品设计的结果，不是你的错；②短视频为什么比书好看——即时反馈vs延迟满足：短视频3秒抓不住你就划走了（内容被迫短平快），书要20分钟进入状态才有收获（大脑嫌慢）——『好看』是设计的，不是内容本身更优秀；③刷短视频放松一下有错吗——没错：短视频是合法的娱乐（信息/笑点/共鸣都有价值），问题在『放松』变『沉迷』：说好刷10分钟，抬头2小时（时间黑洞），刷完空虚（快乐来得快去得也快，没积累）；④不看短视频就落伍吗——不会：短视频只是信息载体之一（新闻/深度内容/书籍都还在），『落伍』焦虑是算法制造的（它让你觉得不看就错过全世界），真重要的信息不会只在短视频里。怎么刷而不沉迷：①物理隔离——关推送通知/设使用时长限额（iOS/安卓都有）/睡前不刷（卧室不带手机）；②用规则代替意志力——『刷之前定个闹钟』『只刷收藏列表』『看3个视频就退出』，别靠『我控制一下』（意志力会耗尽，规则不会）；③内容升级——主动关注有价值创作者（知识/技能/观点），取关无营养账号，让算法喂你更好的（算法可驯服）；④替代满足——想放松就换成书/运动/真人社交（慢娱乐是深度放松，快娱乐是刺激疲劳），『刷完更累』就是沉迷的信号。核心：短视频是工具不是主人——用它获取信息/娱乐，别让它收割你的时间，你的注意力是算法在抢的最贵资源",
    "农村空心化": "农村年轻人越来越少、越来越空，是『个人发展』vs『乡村生机』的矛盾——年轻人进城是因为城市机会多（工作/收入/教育/医疗），农村留不住人是因为机会少（种地不挣钱/没产业/设施差），『空心化』不是年轻人不爱家乡，是市场用脚投票（哪里能活好去哪里）。真相：①为什么农村年轻人越来越少——核心是收入差：种地（一年几亩地赚几千块）vs 进城打工（月入几千），差距十倍；附加是公共服务差（学校撤并/看病难/没娱乐），年轻人留下=孩子教育/老人看病都吃亏——不是观念问题（不想留），是现实问题（留不起）；②农村越来越空谁种地——现实答案：老人种（60-70岁还在种地）、机器种（农业机械化，一人种千亩）、规模化（承包大户/合作社）——『空心化』不等于『没人种地』，而是种地的人变了（从家家户户变成专业化），这是农业现代化的阵痛；③进城打工赚钱有错吗——没错：农民进城是劳动力自由流动（国家政策也鼓励），打工收入养活了农村家庭（老家建房/孩子上学/老人养老都靠它），『留在农村』不是道德义务，是个人选择；④年轻人留在农村有前途吗——现在难，将来有机会：难在当下（产业少/收入低/没同龄人），机会在转变（乡村振兴/乡村旅游/电商助农/现代农业，回乡创业的年轻人越来越多）——关键是『有产业才有前途』，不是口号能留人。怎么留住人：①产业先于口号——因地制宜搞产业（特色农业/加工/乡村旅游/直播电商），年轻人回来有活干有钱赚才留得住；②公共服务补短——乡村教育医疗（学校/卫生室）别撤光，基础设施（网络/路/快递）跟上，宜居才有人住；③政策激励——返乡创业补贴/宅基地改革/职业农民培训，让回得去也活得好；④心态——空心化是城市化的必然阶段（发达国家都经历过），不必恐慌『农村消失』（农村会缩小但不会消失），转型期的重点是让留下的人过得好、让农村有新的活法。核心：农村不缺乡愁缺机会——年轻人不是不想回，是回不去（没产业），振兴的关键是让『回去』和『发展』能同时成立",
    "旅游宰客": "景区宰客、旅游越来越贵，是『游客体验』vs『商家盈利』的矛盾——景区商家做的是『一锤子买卖』（游客来一次就不来了，不指望回头客），宰客是短期最优（能宰一刀是一刀），游客体验被牺牲，长此以往景区口碑崩了，大家都不来了（劣币驱逐良币）。真相：①为什么景区总宰客——信息不对称（游客不熟行情，标价虚高）、一锤子买卖（不指望回头客，宰了也不怕）、监管难（景区内商家多/流动性大/地方保护）——宰客是『短期博弈』的结果，不是商家都坏，是『游客不会再回来』这个结构让人敢宰；②旅游为什么越来越贵——涨价面：门票（景区运营/维护成本高）、住宿餐饮（景区内物价高，运输成本+垄断）、交通（旺季机票酒店翻倍）——部分是成本（景区在山上/岛上，什么都贵），部分是垄断（景区内就那几家，没竞争）；③景区不赚钱怎么维护——真问题：景区维护要钱（设施/保洁/员工），不赚钱就得靠高门票/高物价/过度商业化（卖特产/搞项目）——『宰客』和『维护』不该二选一，但现实是很多景区靠宰客养维护，陷入恶性循环；④商家定价高一点就是宰客吗——不是：成本高（山上的水运输贵）定价高=合理，明码标价+服务对等=正常商业，宰客=『虚标价格/以次充好/强买强卖』（一碗面卖100块还难吃是宰客，明码标价的山顶矿泉水贵是成本）——区别在『透明』和『自愿』。怎么玩得开心不被坑：①行前功课——查攻略/看评价（大众点评/小红书避雷帖），热门景区提前订票（现场买贵且排长队）；②消费策略——景区外买水零食（景区内贵3-5倍）、吃饭看明码标价（先问价再点）、特产理性买（『免费品尝』『大师手作』多数是套路）；③维权意识——被宰了留证据（小票/转账记录），打12315/文旅部门投诉（现在旅游投诉处理很快），别吃哑巴亏（忍气吞声=纵容）；④观念——旅游的本质是体验不是打卡，淡季去（人少价低体验好）、小众目的地（性价比高），『贵』不完全等于『坑』，为体验付费可以，为套路付费不值。核心：景区和游客是长期关系不是一锤子买卖——商家靠口碑才能活，游客靠功课才能不坑，监管到位才能让宰客者付出代价",
    "注意机制": "注意机制是认知资源的选择性分配——选择性注意（聚焦）/分散注意（多任务）/持续注意；对应CSPMN只匹配激活条件空间",'''
    assert anchor_d in src, "daily anchor missing"
    src = src.replace(anchor_d, new_d, 1)
    open(path, "w", encoding="utf-8").write(src)
    print("patched")

